package main

import (
	"fmt"
	"os"
	"strings"

	decimal "github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string
var WsFirstFlag string
var WsPrevBranch string
var WsPrevAcct string
var WsBal decimal.Decimal
var WsBranchTot decimal.Decimal
var WsGrandTot decimal.Decimal
var WsSkipped int64
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var ledgerRec LedgerRec
var lines []string
var lineIdx int

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func storeDecimal(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	vTrunc := v.Truncate(int32(scale))
	if vTrunc.IsZero() {
		return decimal.Zero
	}
	sign := vTrunc.Sign()
	scaled := vTrunc.Shift(int32(scale))
	absScaled := scaled.Abs()
	scaledInt := absScaled.IntPart()
	pow := int64(1)
	for i := 0; i < intDigits+scale; i++ {
		pow *= 10
	}
	mod := scaledInt % pow
	var resInt int64
	if sign < 0 {
		resInt = -mod
	} else {
		resInt = mod
	}
	res := decimal.New(resInt, int32(-scale))
	if res.IsZero() {
		return decimal.Zero
	}
	return res
}

func storeBal(v decimal.Decimal) decimal.Decimal { return storeDecimal(v, 7, 2) }
func storeBranchTot(v decimal.Decimal) decimal.Decimal { return storeDecimal(v, 9, 2) }
func storeGrandTot(v decimal.Decimal) decimal.Decimal { return storeDecimal(v, 9, 2) }

func formatEdited(v decimal.Decimal, pic string) string {
	signed := len(pic) > 0 && pic[0] == '-'
	picBody := pic
	if signed {
		picBody = pic[1:]
	}
	parts := strings.Split(picBody, ".")
	intPic := parts[0]
	decPic := ""
	if len(parts) > 1 {
		decPic = parts[1]
	}
	decDigits := len(decPic)
	intSlots := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intSlots++
		}
	}
	sign := v.Sign()
	abs := v.Abs()
	absTrunc := abs.Truncate(int32(decDigits))
	scaledAbs := absTrunc.Shift(int32(decDigits))
	scaledInt := scaledAbs.IntPart()
	pow := int64(1)
	for i := 0; i < intSlots+decDigits; i++ {
		pow *= 10
	}
	mod := scaledInt % pow
	divisor := int64(1)
	for i := 0; i < decDigits; i++ {
		divisor *= 10
	}
	var intPart, decPart int64
	if decDigits > 0 {
		intPart = mod / divisor
		decPart = mod % divisor
	} else {
		intPart = mod
	}
	digits := make([]int, intSlots)
	tmp := intPart
	for i := intSlots - 1; i >= 0; i-- {
		digits[i] = int(tmp % 10)
		tmp /= 10
	}
	var intOut strings.Builder
	digitIdx := 0
	significantSeen := false
	for _, ch := range intPic {
		switch ch {
		case 'Z':
			d := digits[digitIdx]
			digitIdx++
			if d != 0 {
				intOut.WriteByte(byte('0' + d))
				significantSeen = true
			} else {
				if significantSeen {
					intOut.WriteByte('0')
				} else {
					intOut.WriteByte(' ')
				}
			}
		case '9':
			d := digits[digitIdx]
			digitIdx++
			intOut.WriteByte(byte('0' + d))
			significantSeen = true
		case ',':
			if significantSeen {
				intOut.WriteByte(',')
			} else {
				intOut.WriteByte(' ')
			}
		default:
			intOut.WriteByte(byte(ch))
		}
	}
	var res string
	if decDigits > 0 {
		decStr := fmt.Sprintf("%0*d", decDigits, decPart)
		res = intOut.String() + "." + decStr
	} else {
		res = intOut.String()
	}
	if signed {
		signChar := ' '
		if sign < 0 {
			signChar = '-'
		}
		res = string(signChar) + res
	}
	return res
}

func formatAmtEd(v decimal.Decimal) string { return formatEdited(v, "ZZ,ZZ9.99") }
func formatBalEd(v decimal.Decimal) string { return formatEdited(v, "-Z,ZZZ,ZZ9.99") }
func formatTotEd(v decimal.Decimal) string { return formatEdited(v, "-ZZZ,ZZZ,ZZ9.99") }

func MainPara() {
	content, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	if len(content) == 0 {
		lines = []string{}
	} else {
		raw := string(content)
		parts := strings.Split(raw, "\n")
		if len(parts) > 0 && raw[len(raw)-1] == '\n' {
			parts = parts[:len(parts)-1]
		}
		lines = make([]string, len(parts))
		for i, p := range parts {
			if len(p) > 0 && p[len(p)-1] == '\r' {
				p = p[:len(p)-1]
			}
			lines[i] = p
		}
	}
	lineIdx = 0
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	if WsFirstFlag != "Y" {
		AcctBreakPara()
		BranchBreakPara()
	}
	GrandPara()
}

func ReadPara() {
	if lineIdx < len(lines) {
		rawLine := lines[lineIdx]
		lineIdx++
		var recStr string
		if len(rawLine) < 14 {
			recStr = rawLine + strings.Repeat(" ", 14-len(rawLine))
		} else if len(rawLine) > 14 {
			recStr = rawLine[:14]
		} else {
			recStr = rawLine
		}
		ledgerRec.BrBranch = recStr[0:2]
		ledgerRec.BrAcct = recStr[2:6]
		ledgerRec.BrType = recStr[6:7]
		amtStr := recStr[7:14]
		var amtVal int64
		for i := 0; i < len(amtStr); i++ {
			c := amtStr[i]
			if c >= '0' && c <= '9' {
				amtVal = amtVal*10 + int64(c-'0')
			} else {
				amtVal = amtVal * 10
			}
		}
		ledgerRec.BrAmt = decimal.New(amtVal, -2)
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevBranch = ledgerRec.BrBranch
		WsPrevAcct = ledgerRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if ledgerRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = ledgerRec.BrBranch
			WsPrevAcct = ledgerRec.BrAcct
		} else {
			if ledgerRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = ledgerRec.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func PostPara() {
	WsAmtEd = formatAmtEd(ledgerRec.BrAmt)
	switch ledgerRec.BrType {
	case "D":
		WsBal = storeBal(WsBal.Add(ledgerRec.BrAmt))
		fmt.Printf("%s D %s\n", ledgerRec.BrAcct, WsAmtEd)
	case "C":
		WsBal = storeBal(WsBal.Sub(ledgerRec.BrAmt))
		fmt.Printf("%s C %s\n", ledgerRec.BrAcct, WsAmtEd)
	default:
		WsSkipped = (WsSkipped + 1) % 100
		fmt.Printf("%s ? SKIPPED\n", ledgerRec.BrAcct)
	}
}

func AcctBreakPara() {
	WsBalEd = formatBalEd(WsBal)
	fmt.Printf("  ACCOUNT %s BALANCE:%s\n", WsPrevAcct, WsBalEd)
	WsBranchTot = storeBranchTot(WsBranchTot.Add(WsBal))
	WsBal = decimal.Zero
}

func BranchBreakPara() {
	WsTotEd = formatTotEd(WsBranchTot)
	fmt.Printf(" BRANCH %s TOTAL:%s\n", WsPrevBranch, WsTotEd)
	WsGrandTot = storeGrandTot(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.Zero
}

func GrandPara() {
	WsTotEd = formatTotEd(WsGrandTot)
	fmt.Printf("GRAND TOTAL:%s\n", WsTotEd)
	fmt.Printf("SKIPPED: %02d\n", WsSkipped)
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevBranch = strings.Repeat(" ", 2)
	WsPrevAcct = strings.Repeat(" ", 4)
	WsBal = decimal.Zero
	WsBranchTot = decimal.Zero
	WsGrandTot = decimal.Zero
	WsSkipped = 0
	MainPara()
}
